                if re.match(r'^\s*abstract\s', ln):
                    n = name_of(ln)
                    if not n: continue
                    cb = cmp.get(t)
                    if cb is None:
                        print(f"{f[:-4]}: trait {t} not found in component (member {n})"); continue
                    if not any(name_of(c) == n for c in cb if c.strip()):
                        total += 1
                        print(f"{f[:-4]}: {t}.{n} not declared in the component  [{ln.strip()[:80]}]")
print("total", total)
EOF
